css:
/* Global Styles */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    min-height: 100vh; /* Ensure full viewport height */
}

.container {
    max-width: 100%; /* Further increased max width */
    margin: 0 auto; /* Center the container */
    padding: 30px;
}

/* Header Styling */
.header {
    display: flex;
    justify-content: space-between;
    margin-bottom: 30px;
}

.header .details-left {
    text-align: left; /* Align left for Lead Name and Address */
}

.header .details-right {
    text-align: right; /* Align right for Date and Quotation ID */
}

.header .details {
    font-size: 16px; /* Increased font size */
    line-height: 1.8;
}

/* Title Styling */
.title {
    text-align: center;
    margin-bottom: 30px;
    margin-top: 10px; /* Reduced top margin for Solar EPC heading */
}

/* Table Styling */
.table {
    max-width: 100%; /* Centered and limited width */
    margin: 0 auto; /* Center the table */
    border-collapse: collapse;
    margin-top: 30px;
    font-size: 16px; /* Consistent font size for table data */
}

.table-bordered th, .table-bordered td {
    border: 1px solid #000;
    padding: 8px; /* Reduced padding for smaller cells */
    text-align: left;
}

.table-bordered th {
    background-color: #f0f0f0;
    text-align: center; /* Center align header */
}

/* Responsive Design */
@media (max-width: 768px) {
    .header {
        flex-direction: column;
        text-align: center;
    }

    .table {
        width: 100%; /* Full width on small screens */
    }
}
